class Solution:
    def passesRules(self, word: str) -> bool:
        if len(word) < 3:
            return False
        vowel = consonant = False
        for ch in word:
            if ch.isdigit():
                continue
            low = ch.lower()
            if not ("a" <= low <= "z"):
                return False
            if low in "aeiou":
                vowel = True
            else:
                consonant = True
        return vowel and consonant

